const source = $('Prepare Active Watchlist').item.json;

return items.map(item => {
  const response = item.json;

  const dailyData = Array.isArray(response.data)
    ? response.data
    : Array.isArray(response.body?.data)
      ? response.body.data
      : [];

  return {
    json: {
      symbol: source.symbol,
      company_name: source.company_name || '',
      notes: source.notes || '',
      daily_data: dailyData
    }
  };
});

const sourceItems = $('Store Daily Market Data').all();

return items.map((item, index) => {
  const response = item.json;
  const source = sourceItems[index]?.json || {};

  const weeklyData = Array.isArray(response.data)
    ? response.data
    : Array.isArray(response.body?.data)
      ? response.body.data
      : [];

  return {
    json: {
      symbol: source.symbol || response.symbol || '',
      company_name: source.company_name || '',
      notes: source.notes || '',
      daily: Array.isArray(source.daily_data)
        ? source.daily_data
        : [],
      weekly: weeklyData
    }
  };
});

const VOLUME_MULTIPLIER = 1.5;
const LOOKBACK = 20;

return items.map(item => {
  const data = item.json.daily || [];

  if (data.length < LOOKBACK + 1) {
    return {
      json: {
        ...item.json,
        daily_signal: {
          direction: 'none',
          breakout: false,
          reason: 'Insufficient daily data'
        }
      }
    };
  }

  const current = data[data.length - 1];
  const previous = data.slice(-(LOOKBACK + 1), -1);

  const resistance = Math.max(...previous.map(row => Number(row.high)));
  const support = Math.min(...previous.map(row => Number(row.low)));
  const averageVolume = previous.reduce((sum, row) => sum + Number(row.volume), 0) / previous.length;
  const volumeRatio = Number(current.volume) / averageVolume;

  const bullish = Number(current.close) > resistance && volumeRatio >= VOLUME_MULTIPLIER;
  const bearish = Number(current.close) < support && volumeRatio >= VOLUME_MULTIPLIER;
  const direction = bullish ? 'bullish' : bearish ? 'bearish' : 'none';

  return {
    json: {
      ...item.json,
      daily_signal: {
        direction,
        breakout: direction !== 'none',
        close: Number(current.close),
        resistance: Number(resistance.toFixed(2)),
        support: Number(support.toFixed(2)),
        volume: Number(current.volume),
        average_volume: Math.round(averageVolume),
        volume_ratio: Number(volumeRatio.toFixed(2)),
        volume_threshold: VOLUME_MULTIPLIER
      }
    }
  };
});

return items.map(item => {
  const json = item.json;

  const direction = String(json.final_direction || '').toLowerCase();

  let directionText = 'Breakout';

  if (direction === 'bullish') {
    directionText = 'Bullish breakout';
  } else if (direction === 'bearish') {
    directionText = 'Bearish breakout';
  }

  const symbol = json.symbol || 'Unknown';
  const companyName = json.company_name || 'Unknown company';

  const technicalConfidence = Number(
    json.confidence_score ?? 0
  );

  const confidenceLevel =
    json.confidence_level || 'Unknown';

  const dailyVolumeRatio =
    json.daily_volume_ratio !== undefined
      ? `${json.daily_volume_ratio}x`
      : 'N/A';

  const weeklyVolumeRatio =
    json.weekly_volume_ratio !== undefined
      ? `${json.weekly_volume_ratio}x`
      : 'N/A';

  const narrative =
    json.ai_narrative ||
    'AI analysis unavailable';

  const keyConfirmation =
    json.key_confirmation ||
    'No confirmation summary available';

  const riskNote =
    json.risk_note ||
    'No additional risk note available';

  const message = [
    'Multi-Timeframe Breakout Confirmed',
    '',
    `Symbol: ${symbol}`,
    `Company: ${companyName}`,
    `Direction: ${directionText}`,
    `Confidence: ${technicalConfidence}/100`,
    `Confidence level: ${confidenceLevel}`,
    '',
    `Daily close: ${json.daily_close ?? 'N/A'}`,
    `Daily resistance: ${json.daily_resistance ?? 'N/A'}`,
    `Daily support: ${json.daily_support ?? 'N/A'}`,
    `Daily volume ratio: ${dailyVolumeRatio}`,
    '',
    `Weekly close: ${json.weekly_close ?? 'N/A'}`,
    `Weekly resistance: ${json.weekly_resistance ?? 'N/A'}`,
    `Weekly support: ${json.weekly_support ?? 'N/A'}`,
    `Weekly volume ratio: ${weeklyVolumeRatio}`,
    '',
    `Key confirmation: ${keyConfirmation}`,
    '',
    `AI analysis: ${narrative}`,
    '',
    `Risk note: ${riskNote}`
  ].join('\n');

  return {
    json: {
      ...json,
      slack_message: message
    }
  };
});

return items
  .filter(item => {
    const active = String(item.json.active || '').toLowerCase();
    return active === 'true' || active === '1' || active === 'yes';
  })
  .map(item => ({
    json: {
      symbol: String(item.json.symbol || '').trim().toUpperCase(),
      company_name: item.json.company_name || '',
      notes: item.json.notes || ''
    }
  }))
  .filter(item => item.json.symbol);

const VOLUME_MULTIPLIER = 1.5;
const LOOKBACK = 12;

return items.map(item => {
  const data = item.json.weekly || [];

  // Check whether enough weekly data is available
  if (data.length < LOOKBACK + 1) {
    return {
      json: {
        ...item.json,
        weekly_signal: {
          direction: 'none',
          confirmation: false,
          reason: 'Insufficient weekly data'
        }
      }
    };
  }

  // Current week's data
  const current = data[data.length - 1];

  // Previous 12 weeks
  const previous = data.slice(-(LOOKBACK + 1), -1);

  // Calculate resistance and support
  const resistance = Math.max(
    ...previous.map(row => Number(row.high))
  );

  const support = Math.min(
    ...previous.map(row => Number(row.low))
  );

  // Calculate average volume
  const averageVolume =
    previous.reduce(
      (sum, row) => sum + Number(row.volume),
      0
    ) / previous.length;

  // Calculate current volume vs average volume
  const volumeRatio =
    Number(current.volume) / averageVolume;

  // Determine breakout direction
  const bullish =
    Number(current.close) > resistance &&
    volumeRatio >= VOLUME_MULTIPLIER;

  const bearish =
    Number(current.close) < support &&
    volumeRatio >= VOLUME_MULTIPLIER;

  const direction =
    bullish
      ? 'bullish'
      : bearish
        ? 'bearish'
        : 'none';

  return {
    json: {
      ...item.json,

      weekly_signal: {
        direction,

        confirmation: direction !== 'none',

        close: Number(current.close),

        resistance: Number(
          resistance.toFixed(2)
        ),

        support: Number(
          support.toFixed(2)
        ),

        volume: Number(current.volume),

        average_volume: Math.round(
          averageVolume
        ),

        volume_ratio: Number(
          volumeRatio.toFixed(2)
        ),

        volume_threshold: VOLUME_MULTIPLIER
      }
    }
  };
});

