const originalItem = $('Build Multi Timeframe Signal').item.json;

return items.map(item => {
  const aiResponse = item.json;

  let raw = '';

  if (Array.isArray(aiResponse.output)) {
    for (const outputItem of aiResponse.output) {
      if (!Array.isArray(outputItem.content)) {
        continue;
      }

      for (const contentItem of outputItem.content) {
        if (
          contentItem &&
          contentItem.type === 'output_text' &&
          typeof contentItem.text === 'string'
        ) {
          raw += contentItem.text;
        }
      }
    }
  }

  raw = raw.trim();

  let cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let ai = null;

  try {
    ai = JSON.parse(cleaned);
  } catch (error) {
    const jsonStart = cleaned.indexOf('{');
    const jsonEnd = cleaned.lastIndexOf('}');

    if (jsonStart !== -1 && jsonEnd > jsonStart) {
      const possibleJson = cleaned.substring(
        jsonStart,
        jsonEnd + 1
      );

      try {
        ai = JSON.parse(possibleJson);
      } catch (parseError) {
        ai = null;
      }
    }
  }

  if (!ai || typeof ai !== 'object') {
    ai = {
      confidence_score: originalItem.signal?.confidence_score || 0,
      confidence_level: 'Unknown',
      narrative: raw || 'AI analysis unavailable',
      key_confirmation: '',
      risk_note: ''
    };
  }

  return {
    json: {
      ...originalItem,

      ai_analysis: {
        confidence_score: Number(
          ai.confidence_score ??
          originalItem.signal?.confidence_score ??
          0
        ),

        confidence_level: String(
          ai.confidence_level || 'Unknown'
        ),

        narrative: String(
          ai.narrative || ''
        ).trim(),

        key_confirmation: String(
          ai.key_confirmation || ''
        ).trim(),

        risk_note: String(
          ai.risk_note || ''
        ).trim()
      }
    }
  };
});
